import{_ as t,o as e,c as a,M as s}from"./chunks/framework.b26238a1.js";const h=JSON.parse('{"title":"Contributing to bk-vision","description":"","frontmatter":{},"headers":[],"relativePath":"develop/CONTRIBUTING.md","filePath":"develop/CONTRIBUTING.md"}'),l={name:"develop/CONTRIBUTING.md"},i=s(`<h1 id="contributing-to-bk-vision" tabindex="-1">Contributing to bk-vision <a class="header-anchor" href="#contributing-to-bk-vision" aria-label="Permalink to &quot;Contributing to bk-vision&quot;">​</a></h1><p>欢迎志同道合的开发者一起贡献项目。在开始之前，请认真阅读以下指引。</p><h2 id="代码协议" tabindex="-1">代码协议 <a class="header-anchor" href="#代码协议" aria-label="Permalink to &quot;代码协议&quot;">​</a></h2><h2 id="如何开始" tabindex="-1">如何开始 <a class="header-anchor" href="#如何开始" aria-label="Permalink to &quot;如何开始&quot;">​</a></h2><p>想要贡献代码，建议请先参照已有的特性文档和开发环境构建文档。</p><h2 id="issues" tabindex="-1">Issues <a class="header-anchor" href="#issues" aria-label="Permalink to &quot;Issues&quot;">​</a></h2><p>团队使用 <a href="./.html">issues</a> 进行 bugs 追踪、特性追踪等。</p><p>当提交相关的 bug 时，请查找已存在或者相类似的 issue，从而保证不存在冗余。</p><p>如果确认该 bug 是一个新的 bug，提交时请包含以下的信息：</p><ul><li>你所使用的操作系统信息</li><li>当前你使用的版本信息，例如 version，commitid</li><li>出现问题时，相关模块的日志输出</li><li>重现该问题的准确步骤，例如提交相关重现脚本/工具会比大量描述更有用一些</li></ul><h2 id="pull-request" tabindex="-1">Pull Request <a class="header-anchor" href="#pull-request" aria-label="Permalink to &quot;Pull Request&quot;">​</a></h2><p>Pull Request (简称 PR）是我们使用的主流工作方式，请参考 <a href="https://docs.github.com/en/github/collaborating-with-issues-and-pull-requests/proposing-changes-to-your-work-with-pull-requests/about-pull-requests" target="_blank" rel="noreferrer">Github 文档</a>了解 PR 的功能。我们采用 <a href="https://docs.github.com/en/github/collaborating-with-issues-and-pull-requests/getting-started/about-collaborative-development-models#fork-and-pull-model" target="_blank" rel="noreferrer">&quot;fork and pull&quot;</a> 的开发模式，即开发者首先向自己的 fork 仓库提交变更，然后向上游仓库发起 PR。</p><p>除非有特殊约定，所有 PR 提交的目标分支应始终选择<code>master</code>分支。注意提交 PR 时带着 Issus 的编号。</p><p>此仓库遵循 <em>no merge-commit</em> 原则，当遇到代码冲突时，应使用 rebase （而非 merge）来进行处理。例如，当需要将 master 分支代码合并到特性分支代码进行测试时，始终使用 rebase 进行操作。请在将个人仓库（分支）下产生的零碎 commit 尽量压缩到与之相关的 commit 中，并填写有意义的 commit message，请参考<a href="https://www.atlassian.com/git/tutorials/merging-vs-rebasing" target="_blank" rel="noreferrer">相关资料</a>。</p><p>提交建议的步骤：</p><pre><code>1. fork 代码仓库（第一次操作）；
2. 填写 issue；
3. 在个人仓库下切分支开发，建议按照&quot;&lt;分类&gt;/&lt;issue id&gt;&quot;来设定，比如: feature/#1；
4. 进行开发，此阶段可以根据开发进度自行设置commit；
5. 完成自测，请确保完成相关 issue 功能；
6. 使用 \`git rebase\` 功能准备好发起 PR 的 commit，严格按照 commit message 的规范来填写提交信息；
7. 向主仓库发起 PR（title 仓库默认使用 commit message），并指定好 code review 的负责人；
8. 按照 CR 的意见修改代码。为了避免 CR 负责人在本地反复清理 CR 分支此阶段允许 PR 发起人提交修复类的小 commit，一般使用\`fixup:\`作为 commit 前缀
9. CR 通过；
10. PR 提交者需要将个人仓库下的 fixup commit 进行 \`git rebase\`，确保只有一个 commit；
11. 仓库 master 角色完成 merge（仓库仅开放 rebase merging 选项）；
12. 关闭 issue
</code></pre><h2 id="git-message-规范" tabindex="-1">GIT message 规范 <a class="header-anchor" href="#git-message-规范" aria-label="Permalink to &quot;GIT message 规范&quot;">​</a></h2><p>因不同团队不同的项目管理下会有不同的代码提交注释，规范化开源下对不同团队提交信息，做了不同的提交标记以规范化区分提交内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">git commit -m &#39;标记: 提交的概要注释 issue #123&#39;</span></span></code></pre></div><p>示例:</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">git</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">commit</span><span style="color:#BABED8;"> </span><span style="color:#C3E88D;">-m</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">bugfix: 修复提交问题 #29</span><span style="color:#89DDFF;">&#39;</span></span></code></pre></div><h3 id="标记说明" tabindex="-1">标记说明 <a class="header-anchor" href="#标记说明" aria-label="Permalink to &quot;标记说明&quot;">​</a></h3><table><thead><tr><th style="text-align:left;">标记</th><th style="text-align:center;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">feature</td><td style="text-align:center;">新特性</td></tr><tr><td style="text-align:left;">bugfix</td><td style="text-align:center;">不重要的修改（换行，拼写错误等）</td></tr><tr><td style="text-align:left;">optimization</td><td style="text-align:center;">功能优化</td></tr><tr><td style="text-align:left;">sprintfix</td><td style="text-align:center;">未上线代码修改 （功能模块未上线部分bug）</td></tr><tr><td style="text-align:left;">refactor</td><td style="text-align:center;">功能重构</td></tr><tr><td style="text-align:left;">test</td><td style="text-align:center;">增加测试代码</td></tr><tr><td style="text-align:left;">docs</td><td style="text-align:center;">编写文档</td></tr><tr><td style="text-align:left;">merge</td><td style="text-align:center;">分支合并及冲突解决</td></tr></tbody></table>`,23),r=[i];function o(n,d,c,p,u,m){return e(),a("div",null,r)}const b=t(l,[["render",o]]);export{h as __pageData,b as default};
